sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    // Check if both dates are populated
    var startDate = g_form.getValue('start_date');
    var endDate = g_form.getValue('end_date');

    if (startDate && endDate) {
        // Convert to Date objects for comparison
        var startDateObj = new Date(startDate);
        var endDateObj = new Date(endDate);

        // Compare dates
        if (startDateObj > endDateObj) {
            // Show warning
            g_form.addInfoMessage('Your end date is earlier than your start date. The end date will be adjusted to match the start date when you submit.');

            // Highlight the field
            g_form.showFieldMsg('end_date', 'End date should be on or after start date', 'info');
        } else {
            // Clear any messages
            g_form.clearMessages();
        }
    }
}
